with runtime_clock as ( select format_datetime(now() - interval '24' hour, 'YYYYMMdd') as dt_24h, format_datetime(now() - interval '2' hour, 'YYYYMMdd') as dt_2h, format_datetime(now() - interval '24' hour, 'HH') as hour_24h, format_datetime(now() - interval '3' hour, 'HH') as hour_3h, format_datetime(now() - interval '2' hour, 'HH') as hour_2h ) , biz_qici_calendar as ( select * from ( values ('20260716期', date '2026-07-14', date '2026-07-19'), ('20260722期', date '2026-07-20', date '2026-07-25'), ('20260728期', date '2026-07-26', date '2026-07-31'), ('20260803期', date '2026-08-01', date '2026-08-06'), ('20260809期', date '2026-08-07', date '2026-08-12') ) as t(qici, start_date, end_date) ), market_employee_dim as ( select account_id, employee_email_name, email_prefix, employee_name, is_on_job, job_status, last_resign_date from finance_dw.dim_finance_employee_df t cross join runtime_clock r where t.dt = r.dt_24h and t.first_level_department_name = 'H业务线' and t.second_level_department_name = '市场部' and t.third_level_department_name = '市场顾问部' ), private_stage_latest as ( select user_number, sale_flow_stage_sequence, is_abnormal_stage, case when sale_flow_stage_sequence = '450' then '深沟' when sale_flow_stage_sequence = '470' then '已双沟' else '其他' end as jieduan from ( select p.user_number, p.sale_flow_stage_sequence, case when p.sale_flow_stage_sequence in ('50', '150', '1000') then 1 else 0 end as is_abnormal_stage, row_number() over ( partition by p.user_number order by p.private_sea_update_time desc ) as rn from service_dw.dwd_crm_assign_private_detail_hf p cross join runtime_clock r where p.dt = r.dt_2h and p.hour = r.hour_3h and p.assign_employee_first_level_department_name = 'H业务线' and p.assign_employee_second_level_department_name = '市场部' and p.assign_employee_third_level_department_name = '市场顾问部' ) t where rn = 1 ), lead_stats as ( select lead_id, date_diff( 'hour', cast(section_assign_time as timestamp), cast(section_assign_first_call_connected_time as timestamp) ) as first_call_connected_time_diff_hour from service_dw.dm_crm_lead_stats_detail_hf t cross join runtime_clock r where t.dt = r.dt_2h and t.hour = r.hour_3h and t.mapping_first_level_department_name = 'H业务线' and t.mapping_second_level_department_name in ('精品班学部', '菁英班学部', '市场部', '本地化大班学部') ), abnormal_label as ( select user_number, abnormal_traffic from service_dw.app_user_attribute_label_gaia_wide_df t cross join runtime_clock r where t.dt = r.dt_24h and t.type = 'key' ), double_table as ( select assign_employee_email_name, user_id, send_double_table from ( select t.assign_employee_email_name, t.user_id, t.send_double_table, row_number() over ( partition by t.user_id, t.assign_employee_email_name order by t.trace_update_time desc ) as rn from service_dw.app_h_crm_lead_task_process_info_detail_hf t cross join runtime_clock r where t.dt = r.dt_2h and t.hour = r.hour_3h and t.virtual_department_name_2 = 'H业务线' and t.virtual_department_name_3 = '市场部' ) x where rn = 1 ), call_c as ( select sub.user_number, sub.lead_id, sub.section_assign_employee_email_prefix, max(case when sub.call_duration > 300 then 1 else 0 end) as is_long_call, sum(sub.call_duration) as call_duration_1, sum(case when sub.call_status in ('1', '0') then 1 else 0 end) as zong_call_ci_1, sum(case when sub.call_status = '1' then 1 else 0 end) as call_status_1 from ( select distinct wf.user_number, wf.lead_id, wf.section_assign_employee_email_prefix, wf.call_duration, wf.call_status, wf.call_time, wf.call_type_name, wf.data_source, wf.msg_type_name from service_dw.app_h_crm_lead_employee_workload_detail_hf wf cross join runtime_clock r where wf.dt = r.dt_2h and wf.hour = r.hour_3h ) sub group by sub.user_number, sub.lead_id, sub.section_assign_employee_email_prefix ), f_call0 as ( select a.user_id, b.employee_email_name as assign_employee_email_name, case when sum(if(a.first_call_status = 3, 1, 0)) > 0 then 1 else 0 end as call_answer_lead_count from ( select user_id, first_call_status, account_id from gaotu_crm_offline_statistics.app_mcrm_first_call_task_hf t cross join runtime_clock r where t.dt = r.dt_2h and t.hour = r.hour_3h and t.start_time > '2026-01-01' and t.is_del = 0 ) a left join ( select account_id, employee_email_name from market_employee_dim ) b on a.account_id = b.account_id group by a.user_id, b.employee_email_name ), d_ap as ( select user_latest.user_number, case when user_latest.event_timestamp >= now() - interval '7' day and user_latest.appliction_name in ('PC客户端', 'APP', 'PC') then 1 else 0 end as is_app_denglu_d from ( select ul.user_number, ul.appliction_name, try(date_parse(ul.last_event_time, '%Y-%m-%d %H:%i:%s:%f')) as event_timestamp from ( select t.*, row_number() over ( partition by t.user_number order by try(date_parse(t.last_event_time, '%Y-%m-%d %H:%i:%s:%f')) desc ) as rn from dw.dim_cstm_active_user_c_appliction_mb_df t cross join runtime_clock r where t.dt = r.dt_24h and t.product_name in ('高途', '规划精品') ) ul where rn = 1 ) user_latest ), h_ap as ( select t.user_number, max(case when t.application_name in ('PC客户端', 'APP', 'PC') then 1 else 0 end) as is_app_denglu_h from dw.dws_user_active_user_c_appliction_hf t cross join runtime_clock r where t.dt = r.dt_2h and t.hour = r.hour_3h and t.product_name in ('高途', '规划精品') group by t.user_number ), denglu_app as ( select d_ap.user_number, case when coalesce(h_ap.is_app_denglu_h, 0) = 1 or coalesce(d_ap.is_app_denglu_d, 0) = 1 then 1 else 0 end as is_app_denglu from d_ap left join h_ap on d_ap.user_number = h_ap.user_number ), lead_raw0 as ( select coalesce(lead_cal.qici, concat( date_format( date_trunc( 'week', date_parse(replace(concat(f.group_period_year, f.group_period_term), '期', ''), '%Y%m%d') - interval '1' day ) + interval '4' day, '%Y%m%d' ), '期' )) as pn, f.lead_id as lid, f.user_id as uid, f.employee_email_name as een, f.employee_email_prefix as eep, f.rule_name as rn, f.virtual_third_department_name as d1, f.virtual_fourth_department_name as rd, f.virtual_leader_email_name as rj, f.virtual_direct_leader_email_name as rx, f.flow_pool_name as fp, f.sku_id_name as sku, f.ad_account_name as aa, f.source_manager_name as sm, f.channel_name_1 as c1, f.channel_name_2 as c2, f.channel_name_3 as c3, f.put_plan_name as pp, cast(f.flow_original_order_activity_price as varchar) as foap, cast(f.flow_orders_income_amount as varchar) as foia, cast(f.flow_order_price as varchar) as fop, f.channel_provider_name as cpn, f.channel_second_provider_name as cspn, f.page_id_name as pid, f.source_put_plan_name as spp, f.get_customer_way_name as gcw, f.first_department_name as fd, f.second_department_name as sd, f.third_department_name as td, f.virtual_second_department_name as v2, f.virtual_fourth_department_name as v4, f.virtual_fifth_department_name as v5, f.lead_purchase_intention_name as lpi, f.lead_purchase_intention_level1_category_name as lp1, f.lead_purchase_intention_level2_category_name as lp2, f.lead_create_time as lct, f.section_assign_time as sat, f.first_call_time as fct, f.deep_communicate_method as dcm, f.intention_level as itl, coalesce(f.lead_count, 0) as lead_count, coalesce(f.valid_lead_count, 0) as valid_lead_count, coalesce(f.conversion_lead_count, 0) as conversion_lead_count, coalesce(f.subject_count, 0) as subject_count, coalesce(f.same_lead_period_subject_count, 0) as slps_count, coalesce(f.lb_subject_count, 0) as lb_subject_count, coalesce(f.same_lead_period_lb_subject_count, 0) as slplb_count, coalesce(f.order_count, 0) as order_count, coalesce(f.income_amount, 0) as income_amount, coalesce(f.in_pay_period_refund_amount, 0) as in_pay_period_refund_amount, coalesce(f.non_pay_period_refund_amount, 0) as non_pay_period_refund_amount, coalesce(f.same_lead_period_conversion_lead_count, 0) as slpc_count, coalesce(f.same_lead_period_income_amount, 0) as slpi_amount, coalesce(f.same_lead_period_refund_amount, 0) as slpr_amount, coalesce(f.friend_lead_count, 0) as friend_lead_count, coalesce(f.lead_cost, 0) as lead_cost, coalesce(f.target_lead_cost_per_lead, 0) as target_lead_cost_per_lead, coalesce(f.target_same_department_net_conversion_per_lead, 0) as target_same_department_net_conversion_per_lead from bdg_ba.dm_crm_lead_cost_gmv_communication_learn_full_link_df f cross join runtime_clock r left join biz_qici_calendar lead_cal on cast(date_parse(replace(concat(f.group_period_year, f.group_period_term), '期', ''), '%Y%m%d') as date) between lead_cal.start_date and lead_cal.end_date where f.dt = r.dt_2h and f.hour = r.hour_3h and f.section_assign_employee_first_level_department_name = 'H业务线' and f.section_assign_employee_second_level_department_name = '市场部' and f.section_assign_employee_third_level_department_name = '市场顾问部' and (f.period_mapping_first_level_department_name = 'H业务线' or f.period_mapping_first_level_department_name is null) and ( f.period_mapping_second_level_department_name in ('精品班学部', '菁英班学部', '市场部', '本地化大班学部') or f.period_mapping_second_level_department_name is null ) ), lead_raw as ( select a.*, a.pn not like '%多学科拓展%' as nm, a.td = '直播部' as ld, a.td in ('直播部', '新媒体内容运营部', '市场一组', '私域运营部') as l4, a.td in ('直播部', '新媒体内容运营部', '市场一组') as l3, a.fp like '%自然流%' as nf, a.sm in ('孙晗01','方俊结01','刘亦鹏02','何木玲','杨梓月','张可意03','任颖迪','曹蕊07','曲默晗') as km, a.sm in ('包青青','蔡瑞涵','李文迁','李佳馨44','孙昊17','王洁雅01','王硕北','朱文','贾铭锐','李壮壮04','陈晓菁04','赵艺雅') as smg, a.sm in ('耿文超','晋翠翠','赵语诗','王慧敏13','于新茹','梁超01','刘晓20','王玉120','吕佳乐01') as cmg, a.c1 = '信息流' as ifl, a.c1 = '信息流' and a.c2 = 'B站' as ib, a.c1 = '信息流' and a.c2 = 'B站' and a.td not like '%投放%' as ibn, a.td in ('品牌效能部', 'KOC孵化部') and a.c2 in ('抖音', '视频号', '快手', 'KOL') as ik, regexp_like(a.fp, '孟帝|孟老师|中考数学冲刺|8升9数学|孟亚飞讲数学|中考冲刺|中考满分冲刺|押题王孟亚飞|中考数学大通关|中考数学规划|亚飞数学|孟帝数学|亚飞秒解思维') as yp from lead_raw0 a where a.pn >= ${qici:1} and a.pn < ${qici:2} ), lead_base_all as ( select pn as qici, case
  when rn like '%北京直播江苏%' then '北京直播江苏'
  when gcw in('进校直推','线下渠道商') then '河南进校'
  when gcw in('平台自播')and fp in('赢战广东中考','高途专版图书','状元帮教辅') then '广东图书'
  when gcw in('平台自播')and fp in('途铭文化专版图书','途铭文化','博慧星辰文化图书','启迪蔚来','智慧航迹图书','高途浙江初中','高途浙江高中','高途浙江新高一') then '浙江图书'
  when gcw in('平台自播')and fp in('沪上名校','沪上领航社','简学文化','魔都校友助学馆','沪上领航高中','沪上领航初中') then '上海图书'
  when gcw in('平台自播')and fp in('高途江苏中考','高途赢战中考') then '江苏图书'
  when gcw in('平台自播')and fp in('京赋-浙江科学曹忆规划','为真-浙江科学曹忆老师','为真-浙江大科学曹忆老师','京赋-江苏曹忆老师规划','博学星辰初阶规划峥峥','博学星辰-曹忆老师浙江规划','京赋-浙江曹忆老师规划') then '曹忆'
  when td in('中价产品项目部','新媒体内容运营部')and rn like '%曹忆%' then '曹忆'
  when  ld  and sku like '%山东专版%' then '北京直播山东'
  when  ld  and sku like '%河南专版%' then '北京直播河南'
  when td like '%锋途%' and c2='抖音' then '锋途KOC'
  when (fp like '%江苏预习%' or fp like '%江苏专版预习%')and c2='抖音' then '西安直播江苏-抖音'
  when  nf  and rn like '%江苏%' and td='图书营销部' and c2='抖音' then '西安直播江苏-抖音'
  when (fp like '%江苏预习%' or fp like '%江苏专版预习%')and c2='视频号' then '西安直播江苏-视频号'
  when  nf  and rn like '%江苏%' and td='图书营销部' and c2='视频号' then '西安直播江苏-视频号'
  when rn like '%北京图书%' and td='图书营销部' then '西安直播北京'
  when  nf  and rn like '%北京%' and td='图书营销部' then '西安直播北京'
  when rn like '%语数英%' and td='新媒体内容运营部' then '语数英'
  when fp like '%星义大大%' or fp like '%星义物理%' then '赵星义'
  when rn like '%途途私域%' or(rn like '%私域%' and fd='TT' and rn not like '%集团%') then '途途私域'
  when td='图书营销部' and(sku like '%孟亚飞99%' or sku like '%亚飞%')and c2='百度' then '孟亚飞-2组-百度'
  when td='图书营销部' and(sku like '%孟亚飞99%' or sku like '%亚飞%')and c2='抖音' then '孟亚飞-2组-抖音'
  when td='投放部' and(aa like '%周帅%' or pp like '%周帅%') then '信息流-周帅'
  when sm in('韩正卿') then '抖音私信'
  when td='私域运营部' and sm in('陈雷19','崔慧敏01','侯佳林01','郑天琪02','杨彬屹','曹义鹏','王硕阳','于超研','岳一帆02','田起帆','王绍阳','肖佳兴','姚佳03') then '进校私域合作'
  when c1='市场私域' and(v4 in('郑州学习顾问二部','郑州学习顾问七部','郑州训练营')or v5 in('罗江博团队')) then '市场私域入群'
  when td='图书营销部' and(rn like '%点睛卷%' or sku like '%押题卷%') then '押题卷'
  when td='投放部' and c2='小红书' and c1 <> '搜索营销' then '信息流-小红书'
  when td='线上商务部' and c2='小红书' then '小红书'
  when (fp like '%北大汤哥%' or fp like '%海淀名师高阶%' or fp like '%海淀高阶%')and sku like '%小艺%' then '郭艺'
  when td like '%私域%' and rn like '%私域%' and rn like '%图书%' then '市场私域图书'
  when td like '%私域%' and rn like '%品效%' then '市场私域品效'
  when td like '%私域%' and rn like '%公域学霸%' then '市场私域公域组'
  when  l4 and pp like '%退%' and fp='电商退款用户池' then '退款订单复用'
  when  l4 and pp like '%失败%' and fp='电商退款用户池' then '赠课失败'
  when  l3 and(fp='初阶化学规划' or fp like '%启迪-初阶老师%') then '曹忆'
  when (td='图书营销部' and sku like '%真题%')or( ld  and sku like '%真题%') then '西安图书直播间-直播'
  when (td='图书营销部' and sku not like '%真题%')or( ld  and sku like '%秒懂%')or( ld  and sku like '%图书赠送%') then '西安图书直播间-挂链'
  when  l3 and(fp like '%海淀高阶名师%' or fp like '%海淀老师高阶%' or fp like '%小艺%') then '郭艺'
  when pp like '%国培教育-0元%' or pp like '%易喆教育-0元%' or pp like '%钟情-0元%' or pp like '%中望达-0元%' or pp like '%晨硕-0元%' or pp like '%彩石-0元入群%' then '创新商务入群'
  when td='KOC孵化部' and fp like '%电商退款%' and pp like '%失败%' then '自孵化KOC-赠课失败'
  when td='KOC孵化部' and fp like '%电商退款%' and pp like '%退%' then '自孵化KOC-退款订单复用'
  when sm='方俊结01' and pp like '%赠课后退款%' then 'KOC-赠课后退款'
  when  ld  and(sku like '%春春%' or sku like '%瑞春%' or rn like '%春春%' or rn like '%瑞春%') then '陈瑞春'
  when  ld  and(sku like '%朱博士99%' or rn like '%朱汉祺99%') then '朱博士99'
  when ( ld  and(sku like '%朱博士%' or sku like '%朱汉祺%')and rn like '%9%' and rn not like '%29%' and sku not like '%急%' and sku not like '%礼盒29%')or( ld  and sku like '%朱博士9%') then '朱博士9元'
  when aa like '%春春%' and  ifl  then '信息流-陈瑞春'
  when  ib  and(pid like '%0元物化%') then 'B站信息流-曹忆'
  when  ld  and  ib  then 'B站信息流-亚飞(1元)'
  when  ib  and(pid like '%亚飞%' or spp like '%亚飞%' or rn like '%亚飞%' or pid like '%初中-0元%') then 'B站信息流-亚飞'
  when  ifl  and(pid like '%亚飞%' or aa like '%亚飞%') then '信息流-亚飞'
  when (fp like '%朱博士%' or fp like '%双博士%' or fp like '%教育规划%')and td <> '线上商务部' and  nm  and rn not like '%张杰%' and sku not like '%马凯鹏IP%' and  ld  then '朱博士29'
  when pp like '%朱博士说教育%' and  nm  and fp not like '%高分讲堂%' and fp not like '%总裁%' and  ld  then '朱博士29'
  when (fp like '%朱博士讲英语%' or fp like '%朱博士英语%' or fp like '%朱汉祺说英语%' or fp like '%朱博士说英语%' or fp like '%教育规划%' or fp like '%双博士英语规划%' or fp like '%朱博士满分英语%' or fp like '%英语教父朱博士%' or(fp like '%中考决胜天团%' and lp1='规划系统'))and  ld  and  nm  and sku not like '%马凯鹏IP%' and  ld  then '朱博士29'
  when (fp like '%汤哥%' or fp like '%汤老师%')and  nm  and td in('直播部','新媒体内容运营部') then '汤老师'
  when sm='陈晓菁04' and cpn not like '%开拓%' and pp not like '%九学%' then '商务低价'
  when (fp like '%孟帝%' or fp like '%孟老师%' or fp like '%中考数学冲刺%' or fp like '%8升9数学%' or fp like '%孟亚飞讲数学%' or fp like '%中考冲刺%' or fp like '%中考满分冲刺%' or fp like '%押题王孟亚飞%' or fp like '%中考数学大通关%' or fp like '%中考数学规划%' or fp like '%亚飞数学%' or fp like '%孟帝数学%' or fp like '%亚飞秒解思维%')and  nm  and c2 not like '%KOL%' and  ld  and c2='抖音' then '孟亚飞-1组-抖音'
  when (fp like '%孟帝%' or fp like '%孟老师%' or fp like '%中考数学冲刺%' or fp like '%8升9数学%' or fp like '%孟亚飞讲数学%' or fp like '%中考冲刺%' or fp like '%中考满分冲刺%' or fp like '%押题王孟亚飞%' or fp like '%中考数学大通关%' or fp like '%中考数学规划%' or fp like '%亚飞数学%' or fp like '%孟帝数学%')and  nm  and c2 not like '%KOL%' and  ld  and c2='视频号' then '孟亚飞9元'
  when (fp like '%孟帝%' or fp like '%孟老师%' or fp like '%中考数学冲刺%' or fp like '%8升9数学%' or fp like '%孟亚飞讲数学%' or fp like '%中考冲刺%' or fp like '%中考满分冲刺%' or fp like '%押题王孟亚飞%' or fp like '%中考数学大通关%' or fp like '%中考数学规划%' or fp like '%亚飞数学%' or fp like '%孟帝数学%')and  nm  and c2 not like '%KOL%' and  ld  and c2='B站' then '孟亚飞-1组-B站'
  when (fp like '%孟帝%' or fp like '%孟老师%' or fp like '%中考数学冲刺%' or fp like '%8升9数学%' or fp like '%孟亚飞讲数学%' or fp like '%中考冲刺%' or fp like '%中考满分冲刺%' or fp like '%押题王孟亚飞%' or fp like '%中考数学大通关%' or fp like '%中考数学规划%' or fp like '%亚飞数学%' or fp like '%孟帝数学%')and  nm  and c2 not like '%KOL%' and  ld  and c2 not like '%百度%' then '孟亚飞99-1组'
  when (fp like '%孟帝%' or fp like '%孟老师%' or fp like '%中考数学冲刺%' or fp like '%8升9数学%' or fp like '%孟亚飞讲数学%' or fp like '%中考冲刺%' or fp like '%中考满分冲刺%' or fp like '%押题王孟亚飞%' or fp like '%中考数学大通关%' or fp like '%中考数学规划%' or fp like '%亚飞数学%')and  nm  and c2 not like '%KOL%' and  ld  and c2='百度' then '孟亚飞-1组-百度'
  when (fp like '%孟帝%' or fp like '%孟老师%' or fp like '%中考数学冲刺%' or fp like '%8升9数学%' or fp like '%孟亚飞讲数学%' or fp like '%中考冲刺%' or fp like '%中考满分冲刺%' or fp like '%押题王孟亚飞%' or fp like '%中考数学大通关%' or fp like '%中考数学规划%' or fp like '%亚飞数学%')and  nm  and c2 not like '%KOL%' and  ld  then '孟亚飞9元'
  when pp like '%刘家晋讲图文%' or pp like '%孟帝数学%' and  ld  and rn like '%99%' then '孟亚飞99-1组'
  when pp like '%刘家晋讲图文%' or pp like '%孟帝数学%' and  ld  then '孟亚飞9元'
  when fp like '%汐子%' and  nm  and sku like '%亚飞%' and  ld  and rn like '%99%' then '孟亚飞99-1组'
  when (fp like '%曹忆%' or fp like '%dudu%' or fp like '%中考决胜天团%' or fp like '%具象思维%' or fp like '%在逃发面馒头%' or fp like '%库洛米%' and lp1 <> '规划系统')and  nm  and td in('直播部','新媒体内容运营部') then '曹忆'
  when fd='市场部' and c1 <> '站内获客' and c2 <> 'APP' then '集团私域'
  when td='私域运营部' and rn not like '%训练营%' and v5 not in('罗江博团队')and rn not like '%复用%' and rn not like '%未加好友%' and c2 <> '内部换量' then '市场私域低价单'
  when td='私域运营部' and rn not like '%训练营%' and rn not like '%复用%' and rn not like '%未加好友%' and c2 <> '内部换量' and foap='0.0' then '市场私域低价单'
  when c2 in('APP','M站','PC')and fp not like '%途途%' then 'APP'
  when cpn like '%唐山TMK%' then '唐山TMK'
  when sm in('高文羽')and cpn not like '%唐山TMK%' and cpn not like '%郑州%' then '人工外呼'
  when sm='冯银晨' and c2='小红书' then '信息流-小红书'
  when  ibn  and pid like '%汤雪%' then 'B站信息流-汤学健'
  when ( ifl  and c2 <> 'B站' and td NOT LIKE '%商务%' and pp not like '%初三0元%' and pp not like '%抖音私信%' and pp not like '%高中0元%' and foap not like '%1990%')or(c2='B站' and td like '%投放%') then '信息流'
  when  ibn  and(pid like '%郭艺%') then 'B站信息流-郭艺'
  when  ibn  and(pid like '%朱博士%') then 'B站信息流-朱汉祺'
  when  ibn  and pid like '%肖晗%' then 'B站信息流-肖晗'
  when  ibn  and(pid like '%马凯鹏%' or aa like '%化学%') then 'B站信息流-马凯鹏'
  when  ibn  and(sku like '%陈瑞春%' or rn like '%陈瑞春%')and(aa like '%语文%' or spp like '%自然流%' or pid like '%春春%') then 'B站信息流-陈瑞春'
  when  ibn  and(foap like '%2990%' or sku like '%帅师%' or sku like '%周帅%')and aa like '%语文%' and(foap like '%1980%' or foap like '%2980%' or foap like '%2990%') then 'B站信息流-陈瑞春'
  when  ibn  and(foap like '%2990%' or sku like '%帅师%' or sku like '%周帅%')and aa not like '%语文%' then 'B站信息流-周帅'
  when  ibn  and fop like '%1980%' and aa like '%数学%' then 'B站信息流-周帅'
  when c1='短直电商' and c2='B站' and td like '%商务%' and(fp like '%春春%' or sku like '%陈瑞春%') then 'B站信息流-陈瑞春'
  when c1='短直电商' and c2='B站' and td like '%商务%' and(fp like '%朱博士%') then 'B站信息流-朱汉祺'
  when  ibn  and foap not like '%2980%' and foap not like '%2990%' and foap not like '%1980%' then 'B站信息流'
  when fp='百度搜索引擎' or c1='搜索营销' then '信息流搜索'
  when fp like '%小红书班课%' then '小红书投放'
  when td='投放部' and gcw='短视频信息流' and foap like '%100%' then '信息流'
  when fp='中考加油' and sku like '%孟帝%' then 'KOC-孟亚飞数学'
  when fp='中考加油' and sku like '%帅师%' then 'KOC-周帅数学'
  when  km and(sku like '%孟帝%' or sku like '%dudu%' or sku like '%市场初二%' or rn like '%亚飞%' or sku like '%初二高阳%' or sku like '%高阳初二%' or sku like '%精品初二%' or rn like '%初二%' or sku like '%菁英初三%' or(v2='菁英班学部' and lp2='初级' and lct>='2026-04-15 00:00:00')) then 'KOC-孟亚飞数学'
  when  km and(sku like '%帅师%' or rn like '%周帅%' or sku like '%9月升高三%' or sku like '%新高二%') then 'KOC-周帅数学'
  when  km and(sku like '%肖晗%' or rn like '%肖晗%') then 'KOC-肖晗'
  when  km and  nm  and sku not like '%朱汉祺%' and sku not like '%朱博士%' and sku not like '%周帅%' and sku not like '%29元%' then 'KOC-5元纯课'
  when  km and sku like '%周帅%' then 'KOC-周帅'
  when  ik  then '自孵化KOC-5元纯课'
  when  ik and(sku like '%5元%'or sku like '%11元%' or foap like '%1100%' or foap like '%500%' or foia like '%1100%' or foia like '%500%') then '自孵化KOC-5元纯课'
  when  smg and c2 like '%社群%' then '进校社群'
  when  smg and c2 like '%直推%' then '进校直推'
  when  smg and c2 like '%TMK%' and(pid like '%1元%' or cpn like '%禾顺云%') then '进校TMK1元'
  when  smg and c2 like '%TMK%' and pid like '%9元%' then '进校TMK9元'
  when  smg and c2 like '%书商%' then '进校书商'
  when  smg and c2 like '%综合%' and pp like '%18%' then '进校直播'
  when  smg and c2 like '%直播%' then '进校直播'
  when sm in('包青青','蔡瑞涵','李文迁','李佳馨44','孙昊17','王洁雅01','王硕北','朱文','贾铭锐','李壮壮04','赵艺雅')and pp not like '%0元%' and fp not like '%家校共育%' and fp not like '%保持热爱%' and fp not like '%青松%' and fp not like '%原子初三%' and fp not like '%南通欣创%' and fp not like '%悟之道%' and fp not like '%济南梦航%' and c3 <> '社群' and pp not like '%善悟%' and pp not like '%人人通%' and pp not like '%%济南格乐' and fp not like '%晨硕智学%' and fp not like '%兴尧文化%' and fp not like '%济南映像%' and fp not like '%山东简单%' and fp not like '%争鸣科技%' then '商务低价'
  when fp like '%南通欣创%' or fp like '%人人通科技%' or fp like '%易而购%' or fp like '%济南梦航%' or fp like '%晨硕智学%' or fp like '%兴尧文化%' or fp like '%济南映像%' or fp like '%山东简单%' or fp like '%争鸣科技%' then '进校私域合作'
  when (fp like '%家校共育%' or fp like '%保持热爱%' or fp like '%青松%' or fp like '%悟之道%')and pp not like '%0元%' then '进校私域合作'
  when sm='李宁24' and pp like '%0转低%' then '进校私域合作'
  when td='私域运营部' and foap in('100.0','900.0','300.0') then '进校私域合作'
  when td='私域运营部' and foap in('0.0')and sm in('陈雷19','崔慧敏01','侯佳林01','郑天琪02','杨彬屹','曹义鹏','王硕阳','于超研') then '进校私域合作'
  when td='私域运营部' and c1='市场私域' and pp not like '%公导私%' and pp not like '%公转私%' and foap='0.0' and rn not like '%激活%' and rn not like '%咨询%' and rn not like '%训练营%' and v5 not like '%罗江博%' and v5 not like '%郑州学习顾问二部%' and sm not in('陈雷19','崔慧敏01','侯佳林01','郑天琪02','杨彬屹','曹义鹏','王硕阳','于超研') then '市场私域低价单'
  when  cmg and cpn like '%格乐教育%' and c2 like '%直播%' then '创新社群'
  when  cmg and c2 like '%社群%' then '创新社群'
  when  cmg and(c2 like '%直推%' or pp like '%直推%') then '创新直推'
  when  cmg and(c2 like '%书商%' or pp like '%书商%' or pid like '%书商%') then '创新书商'
  when  cmg and c2 like '%TMK%' and pid like '%1元%' then '创新TMK1元'
  when  cmg and c2 like '%TMK%' and pid like '%9元%' then '创新TMK9元'
  when  cmg and(c2 like '%直播%' or pid like '%进校%') then '创新直播'
  when  cmg and c2<>'公众号' and c1='商务' and fp <> '高途云集图书专营店-自然流' and fp <> '高途旗舰店—线索—yuxinru' and pp not like '%社群%' and pp not like '%小红书班课%' and pp not like '%外部图书供量%' and cspn not like '%沃德丰店铺线索赠课%' and cspn not like '%智慧城-图书%' and pp not like '%育甲%' and fp not like '%周长磊%' then '创新商务'
  when sm in('高曼曼01','杨思怡','宋向函') then '图书KOC达人'
  when fp like '%市场部-微信私域%' or fp like '%市场部-规划报告%' or fp like '%规划报告%' or fp like '%市场部-小红书%' or fp like '%孟浩宇%' then '市场私域低价单'
  when fp like '%未加好友%' then '市场私域未加好友'
  when fp like '公导私' then '进校私域合作'
  when (fp like '%增长组%' or c3='公众号' or sd='微信生态部')and c2 <> 'APP' then '集团私域'
  when pp like '%星耀%' or pp like '%物理展博%' or pp like '%物理谢丽荣%' or pp like '%牟恩伯%' or pp like '%王赞%' or pp like '%张磊老师高中数学%' or pp like '%雯姐高中物理大讲堂%' then '百度星耀'
  when sm='刘福云' and(sku like '%瑞春%' or sku like '%春春%') then '陈瑞春'
  when  ld  and sku like '%周帅%' and c2 in('百度','B站') then '周帅'
  when  ld  and sku like '%孟亚飞%' and rn like '%99%' then '孟亚飞99-1组'
  when  ld  and sku like '%朱汉祺%' then '朱博士29'
  when fp like '%0转低转正%' or c2='产研测试' then '进校私域合作'
  when fp like '%天津智慧双子%' then '创新社群'
  when td like '%城市定制%' then '点睛卷'
  when pn like '%多学科拓展%' and td like '%私域运营%' then '市场私域入群'
  when pp like '%赠课失败%' and td='线上商务部' then 'KOC赠课失败'
  when  nf  and  km and sku like '%周帅%' then 'KOC-周帅'
  when  nf  and  km and sku like '%肖晗%' then 'KOC-肖晗'
  when  nf  and  km and sku like '%朱汉祺%' and foap like '%1100%' then 'KOC-5元朱汉祺'
  when  nf  and sm in('赵语诗','崔文轩','孙培尧') then '自孵化KOC-5元纯课'
  when  nf  and(sku like '%朱博士%' or sku like '%朱汉祺%')and rn like '%9%' and rn not like '%29%' and  l3  then '朱博士9元'
  when  nf  and sku like '%朱博士%' and  l3  then '朱博士29'
  when  nf  and sku like '%亚飞%' and rn like '%99%' and  l3  then '孟亚飞99-1组'
  when  nf  and sku like '%亚飞%' and  l3  then '孟亚飞9元'
  when  nf  and sku like '%曹忆%' then '曹忆'
  when  nf  and rn like '%朱博士%' and  l3  then '朱博士29'
  when  nf  and sm like '%邵万昕%' and  l3  then '朱博士29'
  when  nf  and rn like '%亚飞%' and rn like '%99%' then '孟亚飞99-1组'
  when  nf  and rn like '%亚飞%' then '孟亚飞9元'
  when  nf  and rn like '%郭艺%' then '郭艺'
  when  nf  and rn like '%汤雪%' then '汤老师'
  when  nf  and rn like '%曹忆%' then '曹忆'
  when fp like '%途途教室%' or fd like 'TUTU' then '途途APP'
  when sm in('宋莹莹','辛世如')and c2 in('视频号') then '信息流-虚拟号挂车'
  when rn like '%训练营%' and rn like '%市场私域%' then '市场私域入群'
  when  ifl  and(pp like '%抖音私信%' or pp like '%初三0元%' or pp like '%高中0元%') then '信息流-抖音私信'
  when rn like '%途途私域%' or(rn like '%私域%' and fd='TT') then '途途私域'
  else '其他未知流量'
end as channel, case when rn like '%高一%' then '高一' when rn like '%高二%' then '高二' when rn like '%高三%' then '高三' when rn like '%初一%' then '初一' when rn like '%初二%' then '初二' when rn like '%初三%' then '初三' else lp2 end as grade, lid as lead_id, uid as user_id, een as employee_email_name, eep as employee_email_prefix, rn as rule_name, d1 as depart_1, rd as raw_department, rj as raw_jingli, rx as raw_zhuguan, sat as section_assign_time, fct as first_call_time, dcm as deep_communicate_method, itl as intention_level, lead_count, valid_lead_count, conversion_lead_count, subject_count, slps_count as same_lead_period_subject_count, lb_subject_count, slplb_count as same_lead_period_lb_subject_count, order_count, income_amount, in_pay_period_refund_amount, non_pay_period_refund_amount, slpc_count as same_lead_period_conversion_lead_count, slpi_amount as same_lead_period_income_amount, slpr_amount as same_lead_period_refund_amount, friend_lead_count, lead_cost, target_lead_cost_per_lead, target_same_department_net_conversion_per_lead from lead_raw ), lead_org_all as ( select b.qici, b.channel, b.grade, b.lead_id, b.employee_email_name, b.employee_email_prefix, b.raw_department as department, b.raw_jingli as jingli, b.raw_zhuguan as xiaozu from lead_base_all b ), lead_base as ( select * from lead_base_all where qici >= ${qici:1} and qici < ${qici:2} ), lead_org as ( select * from lead_org_all where qici >= ${qici:1} and qici < ${qici:2} ), learn_raw as ( select t.user_number, t.clazz_number, t.clazz_lesson_number, t.lesson_index, t.lesson_index_add, t.begin_time, coalesce(learn_cal.qici, case when cast(t.begin_time as date) >= date '2026-02-25' and cast(t.begin_time as date) <= date '2026-03-02' then '20260227期' when cast(t.begin_time as date) >= date '2026-02-17' and cast(t.begin_time as date) <= date '2026-02-24' then '20260220期' when cast(t.begin_time as date) >= date '2026-02-09' and cast(t.begin_time as date) <= date '2026-02-16' then '20260213期' when cast(t.begin_time as date) >= date '2026-02-03' and cast(t.begin_time as date) <= date '2026-02-08' then '20260206期' else case when day_of_week(cast(t.begin_time as date)) = 2 then date_format(date_trunc('week', cast(t.begin_time as timestamp)) - interval '3' day, '%Y%m%d') || '期' else date_format(date_trunc('week', cast(t.begin_time as timestamp)) + interval '4' day, '%Y%m%d') || '期' end end) as qici, t.live_learn_duration, t.is_valid_live_learn from service_dw.dws_service_user_learn_detail_hf t cross join runtime_clock r left join biz_qici_calendar learn_cal on cast(t.begin_time as date) between learn_cal.start_date and learn_cal.end_date where t.dt = r.dt_2h and t.hour = r.hour_2h and t.course_first_level_department_name = 'H业务线' and t.course_second_level_department_name in ('精品班学部', '市场部', '青橙项目部') and t.is_need_attend = 1 ), learn_ranked as ( select lr.*, row_number() over ( partition by lr.qici, lr.user_number, lr.clazz_number order by cast(lr.begin_time as timestamp), lr.clazz_lesson_number ) as lesson_rank_in_class, cast( case when lr.lesson_index between 1 and 6 then lr.lesson_index when lr.lesson_index_add between 1 and 6 then lr.lesson_index_add else row_number() over ( partition by lr.qici, lr.user_number, lr.clazz_number order by cast(lr.begin_time as timestamp), lr.clazz_lesson_number ) end as varchar ) as auto_ke_1 from learn_raw lr ), lead_learn_bridge as ( select b.qici, b.channel, b.grade, b.lead_id, b.user_id, b.employee_email_prefix, lr.begin_time, lr.live_learn_duration, lr.is_valid_live_learn, lr.auto_ke_1 from lead_base b left join learn_ranked lr on b.qici = lr.qici and cast(b.user_id as varchar) = cast(lr.user_number as varchar) ), attendance_detail as ( select llb.qici, llb.channel, llb.grade, llb.lead_id, llb.user_id, llb.employee_email_prefix, llb.live_learn_duration, llb.is_valid_live_learn, llb.auto_ke_1 as manual_ke_1 from lead_learn_bridge llb ), attendance_by_lead as ( select qici, channel, grade, lead_id, user_id, employee_email_prefix, max(case when manual